import {createPersonnelViews} from './personnel-view.mjs';
import {hasSensitive} from './admin-permissions.mjs';
import {renderKnowledgeNavigation} from './knowledge-navigation.mjs';
import {maskContact} from './resource-model.mjs';
export const resourcePages=new Set(['templates','titles','tools','knowledge','learning','members','accounts','shops','profile']);
export function createResourceViews({api,h,heading,showPanel,source,localTime,notify,writable=false}){
 createPersonnelViews({api,h,showPanel,localTime});
 const $=s=>document.querySelector(s);
 const blank=(title,desc)=>`<div class="empty"><h3>${h(title)}</h3><p>${h(desc)}</p></div>`;
 const head=title=>`<div class="dialog-header"><h2>${h(title)}</h2><button class="icon-button" data-resource-close aria-label="关闭资料详情">×</button></div>`;
 const tags=items=>`<div class="tag-list">${(items||[]).map(x=>`<span>${h(x)}</span>`).join('')}</div>`;
 const facts=pairs=>`<dl class="record-facts">${pairs.map(([label,v])=>`<div><dt>${h(label)}</dt><dd>${h(v??'未填写')}</dd></div>`).join('')}</dl>`;
 const disabled=label=>`<button class="secondary" disabled title="当前为云端只读预览">${h(label)}</button>`;
 let onOpen=null,onCopy=null,canMaintain=false,canLinkLogin=false;
 document.addEventListener('click',e=>{const open=e.target.closest('[data-resource-open]'),copy=e.target.closest('[data-title-copy]'),close=e.target.closest('[data-resource-close]');if(open)onOpen?.(open.dataset.resourceOpen);if(copy)onCopy?.(copy.dataset.titleCopy);if(close)$('#cloud-detail').close();});
 function templates(rows){
  $('#main').innerHTML=heading('模板库','找到可复用的结构，把已经验证过的做法留下来。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找模板<input id="template-search" type="search" placeholder="名称、结构、产品或标签"></label><label>范围<select id="template-scope"><option value="active">在用模板</option><option value="all">全部模板</option><option value="archived">已归档</option></select></label>${disabled('＋ 新建模板')}</div><div class="material-grid" id="template-grid"></div></section>`;
  onOpen=id=>showPanel('模板详情',async signal=>{const t=await api.template(id,signal);return head(t.name)+`<div class="detail-meta"><span class="type-tag">${h(t.archived?'已归档':'在用模板')}</span><span>${h(t.product||'未指定产品')}</span><span>${h(t.scene||'未指定场景')}</span></div>${tags(t.tags)}<div class="detail-content"><h3>内容结构</h3><p class="preserve-text">${h(t.structure||'暂无结构说明')}</p><h3>使用说明</h3><p class="preserve-text">${h(t.description||'暂无说明')}</p>${t.benchmarkUrl?source(t.benchmarkUrl):''}<h3>相关来源</h3>${t.sourceMaterialId?`<button class="linked-record" data-live-material="${h(t.sourceMaterialId)}">查看来源素材 →</button>`:''}${t.sourceExperimentId?`<button class="linked-record" data-live-test="${h(t.sourceExperimentId)}">查看关联实验 →</button>`:''}<h3>已有使用安排 · ${t.usages.length}</h3>${t.usages.map(u=>`<button class="linked-record" data-live-task="${h(u.id)}"><b>${h(u.title)}</b><span>${h(u.accountName||'未提供账号')} →</span></button>`).join('')||'<p class="muted">暂无可见使用安排。</p>'}<div class="action-row">${disabled('引用到内容安排')}${disabled('编辑模板')}</div></div>`;});
  const render=()=>{const q=$('#template-search').value.trim().toLowerCase(),scope=$('#template-scope').value;const list=rows.filter(t=>(scope==='all'||t.archived===(scope==='archived'))&&[t.name,t.structure,t.product,...t.tags].join(' ').toLowerCase().includes(q));$('#template-grid').innerHTML=list.map(t=>`<article class="material-card"><div class="material-card-top"><span class="type-tag">${h(t.product||'通用模板')}</span><span class="muted">${h(t.archived?'已归档':'在用')}</span></div><button class="material-title" data-resource-open="${h(t.id)}">${h(t.name)}</button><p class="material-excerpt">${h(t.structure||t.description||'暂无结构说明')}</p>${tags(t.tags)}<div class="material-card-foot"><span>${t.stats?.publishedCount??'未提供'} 篇关联发布</span><button data-resource-open="${h(t.id)}">查看结构 →</button></div></article>`).join('')||blank('没有符合条件的模板','可以更换关键词或查看归档内容。');};$('#template-search').oninput=render;$('#template-scope').onchange=render;render();
 }
 async function titles(signal){
  $('#main').innerHTML=heading('标题库','按批次整理标题，让好表达随时能找到。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找标题批次<input id="title-search" type="search" placeholder="批次名称、标题或方向"></label>${disabled('＋ 新建标题批次')}</div><div id="title-batches"><p class="muted">正在读取标题目录…</p></div><div class="pager"><button class="secondary" id="title-prev">上一页</button><span id="title-page"></span><button class="secondary" id="title-next">下一页</button></div></section>`;
  let page=1,q='',request,serial=0,timer;
  const load=async()=>{request?.abort();request=new AbortController();const current=++serial;const combined=AbortSignal.any([signal,request.signal]);try{const data=await api.titleCatalog({page,q},combined);if(combined.aborted||current!==serial)return;page=data.page;$('#title-batches').innerHTML=data.items.map(b=>`<button class="title-batch-card" data-resource-open="${h(b.id)}"><div class="batch-symbol">Aa</div><div><b>${h(b.name)}</b><p>${h(b.batchDate||'日期未提供')} · ${b.titleCount} 条标题 · ${b.directionCount} 个方向</p>${tags(b.directions)}</div><span class="task-arrow">›</span></button>`).join('')||blank('没有符合条件的标题批次','试试其他关键词。');$('#title-page').textContent=`${data.page} / ${data.pageCount} 页 · ${data.total} 个批次`;$('#title-prev').disabled=data.page<=1;$('#title-next').disabled=data.page>=data.pageCount;}catch(e){if(e.name==='AbortError'||signal.aborted)return;$('#title-batches').innerHTML=blank('标题目录读取失败',e.message);}};
  onOpen=id=>showPanel('标题批次',async s=>{const batch=await api.titleBatch(id,s);const items=new Map(batch.items.map(t=>[t.id,t]));onCopy=async key=>{const item=items.get(key);if(!item)return;try{await navigator.clipboard.writeText(item.title);notify('标题已复制，未新增使用记录');}catch{notify('浏览器未允许复制，请选中文字复制');}};return head(batch.name)+`<div class="detail-meta"><span>${h(batch.batchDate)}</span><span>${batch.items.length} 条标题</span></div>${batch.items.map(item=>`<article class="title-entry"><span class="type-tag">${h(item.direction||'未分类')}</span><p>${h(item.title)}</p><div><small>${item.usageCount??'未提供'} 次已记录使用</small><button class="text-button" data-title-copy="${h(item.id)}">复制标题</button></div></article>`).join('')}`;});
  $('#title-search').oninput=e=>{q=e.target.value;page=1;clearTimeout(timer);timer=setTimeout(()=>{if(!signal.aborted)load();},250);};$('#title-prev').onclick=()=>{page--;load();};$('#title-next').onclick=()=>{page++;load();};signal.addEventListener('abort',()=>{clearTimeout(timer);request?.abort();},{once:true});await load();
 }
 function tools(rows){
  $('#main').innerHTML=heading('工具箱','把常用工具放在手边，少一点寻找和重复询问。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找工具<input id="tool-search" type="search" placeholder="工具名称、用途或分类"></label><label>分类<select id="tool-category"><option value="all">全部分类</option>${[...new Set(rows.map(t=>t.category||'未分类'))].map(v=>`<option>${h(v)}</option>`).join('')}</select></label>${disabled('＋ 添加工具')}</div><div class="tool-grid" id="tool-grid"></div></section>`;
  const render=()=>{const q=$('#tool-search').value.trim().toLowerCase(),category=$('#tool-category').value;const list=rows.filter(t=>(category==='all'||(t.category||'未分类')===category)&&[t.name,t.description,t.category].join(' ').toLowerCase().includes(q));$('#tool-grid').innerHTML=list.map(t=>`<article class="tool-card"><span class="tool-symbol">↗</span><div><span class="type-tag">${h(t.category||'未分类')}</span><h2>${h(t.name)}</h2><p>${h(t.description||'暂无用途说明')}</p>${source(t.url)}</div></article>`).join('')||blank('暂时没有符合条件的工具','试试其他分类或关键词。');};$('#tool-search').oninput=render;$('#tool-category').onchange=render;render();
 }
 function knowledge(rows,page){
  const type=page==='learning'?'learning':'knowledge',list=rows.filter(k=>k.entryType===type);const title=page==='learning'?'学习与复盘':'知识库';
  $('#main').innerHTML=heading(title,page==='learning'?'把学习过程、案例拆解和下一步行动留在一起。':'让团队的方法、规范和长期经验容易找到。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找内容<input id="knowledge-search" type="search" placeholder="标题、摘要或标签"></label><label>分类<select id="knowledge-category"><option value="all">全部分类</option>${[...new Set(list.map(k=>k.category||'未分类'))].map(v=>`<option>${h(v)}</option>`).join('')}</select></label>${disabled('＋ 新建内容')}</div><div id="knowledge-list"></div></section>`;
  onOpen=id=>{const item=list.find(k=>k.id===id);if(!item)return;showPanel(item.title,async()=>head(item.title)+`<div class="detail-meta"><span class="type-tag">${h(item.category||'未分类')}</span><span>更新 ${h(localTime(item.updatedAt))}</span></div>${tags(item.tags)}<div class="detail-content">${item.summary?`<p class="article-lead">${h(item.summary)}</p>`:''}${item.kind==='article'?`<div class="article-body">${h(item.body||'暂无正文')}</div>`:item.kind==='link'?`<p class="muted">正文由来源文档维护，打开时仍需具备对应访问权限。</p>${source(item.sourceUrl)}`:`<h3>引用的测试结论</h3><p class="preserve-text">${h(item.sourceFinding||'来源结论暂不可用')}</p><p class="muted">${h(item.sourceRecommendation||'')}</p>${item.sourceParentId?`<button class="linked-record" ${item.sourceKind==='experiment'?'data-live-test':'data-product-detail'}="${h(item.sourceParentId)}">查看原始${item.sourceKind==='experiment'?'实验':'产品'} →</button>`:''}`}</div>`);};
  const render=()=>{const q=$('#knowledge-search').value.trim().toLowerCase(),category=$('#knowledge-category').value;const result=list.filter(k=>(category==='all'||(k.category||'未分类')===category)&&[k.title,k.summary,...k.tags].join(' ').toLowerCase().includes(q));$('#knowledge-list').innerHTML=result.map(k=>`<button class="knowledge-row" data-resource-open="${h(k.id)}"><span class="knowledge-symbol">${k.kind==='link'?'↗':k.kind==='conclusion'?'✓':'▤'}</span><span><small>${h(k.category||'未分类')}</small><b>${h(k.title)}</b><p>${h(k.summary||'暂无摘要')}</p>${tags(k.tags)}</span><span class="knowledge-date">${h((k.updatedAt||'').slice(0,10))} ›</span></button>`).join('')||blank('还没有符合条件的内容','换个关键词，或回到全部分类。');};$('#knowledge-search').oninput=render;$('#knowledge-category').onchange=render;render();
 }
 function members(rows,user){
  $('#main').innerHTML=heading('团队成员','了解每个人的分工，保持成员档案与登录身份的关联。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找成员<input id="member-search" type="search" placeholder="姓名、岗位或在职状态"></label>${canMaintain?'<button class="primary" data-directory-kind="member">＋ 添加成员</button>':disabled('＋ 添加成员')}</div><div class="member-grid" id="member-grid"></div></section>`;
  onOpen=id=>{const m=rows.find(r=>r.id===id);showPanel('成员资料',async()=>head(m.displayName)+(canMaintain?`<button class="secondary" data-directory-kind="member" data-directory-id="${h(m.id)}">编辑成员资料</button><button class="secondary" data-employment-dates="${h(m.id)}">在职适用日期</button>${canLinkLogin&&!m.loginAccountId?`<button class="secondary" data-member-login="${h(m.id)}">关联登录账号</button>`:''}`:'')+`${hasSensitive(user,'personnel')?`<button class="secondary" data-personnel-history="${h(m.id)}">资料变更历史</button>`:'<p class="muted">当前仅提供关联所需的基础人员目录，人员细节需单独授权。</p>'}`+facts([['岗位',m.jobTitle],['入职日期',m.startDate],['最后在职日（含当天）',m.endDate],['在职状态',m.employmentStatus],['业务参与',m.active?'启用':'停用'],['登录关联',m.loginAccountId?'已关联':'未关联'],['登录状态',m.loginAccountId?(m.loginActive?'启用':'停用'):'未关联']])+`<p class="muted">成员业务状态与登录账号状态分别管理。本页不推断考勤、工资或绩效。</p>`);};
  const render=()=>{const q=$('#member-search').value.trim().toLowerCase();$('#member-grid').innerHTML=rows.filter(m=>[m.displayName,m.jobTitle,m.employmentStatus].join(' ').toLowerCase().includes(q)).map(m=>`<button class="member-card" data-resource-open="${h(m.id)}"><span class="member-avatar">${h(m.displayName.slice(0,1))}</span><b>${h(m.displayName)}</b><p>${h(m.jobTitle||'岗位未填写')}</p><span class="type-tag">${h(m.employmentStatus||(m.active?'业务启用':'业务停用'))}</span><small>${m.loginAccountId?'已关联登录身份':'尚未关联登录身份'}</small></button>`).join('')||blank('没有符合条件的成员','请调整关键词。');};$('#member-search').oninput=render;render();
 }
 function accounts(rows){
  $('#main').innerHTML=heading('账号管理','这里管理业务运营账号，保留负责人和使用状态。')+`<section class="work-panel module-panel"><div class="module-toolbar"><label class="module-search">查找运营账号<input id="account-search" type="search" placeholder="账号名称或负责人"></label><label>范围<select id="account-scope"><option value="active">启用账号</option><option value="all">全部账号</option><option value="inactive">停用账号</option></select></label>${canMaintain?'<button class="primary" data-directory-kind="account">＋ 添加账号</button>':disabled('＋ 添加账号')}${canMaintain?'<button class="secondary" data-open-phone-cards>手机卡档案与关联</button>':''}</div><div id="account-list"></div></section>`;
  onOpen=id=>{const a=rows.find(r=>r.id===id);showPanel('运营账号',async()=>head(a.name)+(canMaintain?`<button class="secondary" data-open-phone-cards data-phone-account="${h(a.id)}">查看关联手机卡</button>`:'')+facts([['负责人',a.responsibleName],['使用状态',a.active?'启用':'停用'],['关联成员',a.memberActive?'业务启用':'业务停用'],['绑定号码',maskContact(a.boundPhone)],['实际号码',maskContact(a.actualPhone)]])+source(a.profileUrl)+`<div class="detail-content"><h3>备注</h3><p class="preserve-text">${h(a.remark||'暂无备注')}</p></div>`);};
  const render=()=>{const q=$('#account-search').value.trim().toLowerCase(),scope=$('#account-scope').value;$('#account-list').innerHTML=rows.filter(a=>(scope==='all'||a.active===(scope==='active'))&&[a.name,a.responsibleName].join(' ').toLowerCase().includes(q)).map(a=>`<button class="account-row" data-resource-open="${h(a.id)}"><span class="account-symbol">小</span><span><b>${h(a.name)}</b><small>${h(a.responsibleName||'负责人未提供')}</small></span><span class="type-tag">${a.active?'启用':'停用'}</span><span class="task-arrow">›</span></button>`).join('')||blank('没有符合条件的运营账号','可以更换筛选范围。');};$('#account-search').oninput=render;$('#account-scope').onchange=render;render();
 }
 function shops(rows){$('#main').innerHTML=heading('店铺资料','统一维护店铺基础档案，供产品与业务记录引用。')+`<section class="work-panel module-panel"><div class="module-toolbar"><span class="muted">${rows.length} 个店铺档案</span>${canMaintain?'<button class="primary" data-directory-kind="store">＋ 新建店铺</button>':disabled('＋ 新建店铺')}</div>${rows.map(s=>`<article class="account-row"><span class="account-symbol">店</span><span><b>${h(s.name)}</b><small>版本 ${h(s.version)}</small></span><span class="type-tag">${s.active?'启用':'停用'}</span>${canMaintain?`<button class="secondary" data-directory-kind="store" data-directory-id="${h(s.id)}">编辑店铺</button><button class="secondary" data-open-phone-cards data-phone-store="${h(s.id)}">关联手机卡</button>`:''}</article>`).join('')||blank('暂无店铺资料','后续创建的店铺会由产品与财务共同引用。')}</section>`;}
 function profileView(profile,user){$('#main').innerHTML=heading('个人资料','查看本人的登录身份与成员基础资料。')+`<section class="work-panel planning-panel">${facts([['登录用户名',user.username],['角色',user.role==='admin'?'管理员':'员工'],['成员姓名',profile?.display_name||profile?.displayName||'尚未关联'],['岗位',profile?.job_title||profile?.jobTitle],['入职日期',profile?.start_date||profile?.startDate],['最后在职日（含当天）',profile?.end_date||profile?.endDate],['在职状态',profile?.employment_status||profile?.employmentStatus]])}<p class="muted">登录资料与成员档案按实际关联展示，不自动修改角色或账号状态。</p></section>`;}
 return {async render(page,signal,user,profile){
  onOpen=null;onCopy=null;canMaintain=writable&&(page==='members'?hasSensitive(user,'personnel'):['accounts','shops'].includes(page)?hasSensitive(user,'resources'):user.role==='admin');canLinkLogin=canMaintain&&hasSensitive(user,'account_security');
  if(page==='templates'){const rows=await api.templates(signal);if(!signal.aborted)templates(rows);}
  if(page==='titles')await titles(signal);
  if(page==='tools'){const rows=await api.tools(signal);if(!signal.aborted)tools(rows);}
  if(page==='knowledge'||page==='learning'){const rows=await api.knowledge(signal);if(!signal.aborted){if(page==='knowledge')renderKnowledgeNavigation({rows,user,signal,api,h,heading,notify,writable});else knowledge(rows,page);}}
  if(page==='members'){const rows=await api.members(signal);if(!signal.aborted)members(rows,user);}
  if(page==='accounts'){const rows=await api.businessAccounts(signal);if(!signal.aborted)accounts(rows);}
  if(page==='shops'){const rows=await api.stores(signal);if(!signal.aborted)shops(rows);}
  if(page==='profile')profileView(profile,user);
 }};
}
